import { Routes } from "@angular/router";
import { AdminComponent } from "./admin/admin.component";
import { AdminAddComponent } from "./admin/admin-add/admin-add.component";
import { StudentComponent } from "./student/student.component";
import { StudentAddComponent } from "./student/student-add/student-add.component";
import { TeacherComponent } from "./teacher/teacher.component";
import { TeacherAddComponent } from "./teacher/teacher-add/teacher-add.component";
import { ParentComponent } from "./parent/parents.component";
import { ParentAddComponent } from "./parent/parent-add/parents-add.component";
import { RoutezFeatureModule } from "@_core/_route";

export const Routez: Routes = new RoutezFeatureModule (
  ['User'],
  'feature/user'
)
.feature(AdminComponent, AdminAddComponent, 'admin', 'Admin')
.feature(TeacherComponent, TeacherAddComponent, 'teacher', 'Teacher')
.feature(ParentComponent, ParentAddComponent, 'parent', 'Parent')
.feature(StudentComponent, StudentAddComponent, 'student', 'Student Profile')
.build();
